{
  "name": "todomvc-shakedown",
  "version": "0.1.0",
  "private": true,
  "scripts": { "test": "cucumber-js" },
  "devDependencies": { "@cucumber/cucumber": "*", "happy-dom": "*" }
}

arguments.content:
{
  "watches": [
    {
      "name": "todo-management-basics",
      "scenarios": [
        "features/todo-management.feature:App shows input field and hides main and footer when there are no todos",
        "features/todo-management.feature:User adds a new todo by pressing Enter",
        "features/todo-management.feature:User adds a todo with whitespace-only text",
        "features/todo-management.feature:User adds a todo with trimmed text"
      ]
    },
    {
      "name": "todo-management-counters",
      "scenarios": [
        "features/todo-management.feature:Counter shows the number of active todos with correct pluralization",
        "features/todo-management.feature:Clear completed button removes all completed todos",
        "features/todo-management.feature:Clear completed button is hidden when there are no completed todos"
      ]
    },
    {
      "name": "todo-toggling",
      "scenarios": [
        "features/todo-toggling.feature:User marks a todo as completed by clicking its checkbox",
        "features/todo-toggling.feature:Mark all as complete checkbox toggles all todos",
        "features/todo-toggling.feature:Mark all as complete checkbox reflects individual toggles",
        "features/todo-toggling.feature:Toggle-all checkbox is unchecked when not all todos are completed",
        "features/todo-toggling.feature:Clear completed resets toggle-all checkbox state"
      ]
    },
    {
      "name": "todo-editing",
      "scenarios": [
        "features/todo-editing.feature:User enters edit mode by double-clicking a todo label",
        "features/todo-editing.feature:User saves an edit by pressing Enter",
        "features/todo-editing.feature:User saves an edit by blurring the input",
        "features/todo-editing.feature:User discards an edit by pressing Escape",
        "features/todo-editing.feature:User clears an item by editing to empty text",
        "features/todo-editing.feature:User clears an item by editing to whitespace-only text",
        "features/todo-editing.feature:Todo title is trimmed on save"
      ]
    },
    {
      "name": "todo-persistence",
      "scenarios": [
        "features/todo-persistence.feature:Todos are saved to localStorage",
        "features/todo-persistence.feature:Completed state is persisted to localStorage",
        "features/todo-persistence.feature:Todos are restored from localStorage on page load",
        "features/todo-persistence.feature:Editing state is not persisted",
        "features/todo-persistence.feature:Todos use correct data format"
      ]
    },
    {
      "name": "todo-routing",
      "scenarios": [
        "features/todo-routing.feature:Default route shows all todos",
        "features/todo-routing.feature:Active route shows only active todos",
        "features/todo-routing.feature:Completed route shows only completed todos",
        "features/todo-routing.feature:Filter selection is persisted on reload",
        "features/todo-routing.feature:Toggling an item in a filtered view hides it"
      ]
    }
  ]
}
